-- MTwin HUB: a pinned copy of lucide-roblox-direct (MIT, see LICENSE), commit 7d3ec23 (2026-11-01).
-- The original keeps its sprite sheets in a folder every script on the executor shares: another
-- script with a different icon version overwrote them and every icon in our menus showed the wrong
-- picture. Ours live in "MTwinHub/icons/" and only change when we update this copy.
local Lucide = {}

local IS_GETCUSTOMASSET_BROKEN = false
local VERSION = "2026-11-01T04:40:16.702017403+00:00"
local FOLDER = "MTwinHub/icons"
local SHEETS = "https://raw.githubusercontent.com/mammot41038-beep/MTwin-UI/main/icons/"

if writefile and isfolder and makefolder and getcustomasset then
	local Ok = pcall(function()
		if not isfolder("MTwinHub") then
			makefolder("MTwinHub")
		end

		if not isfolder(FOLDER) then
			makefolder(FOLDER)
		end

		local ShouldUpdate = not isfile(FOLDER .. "/version.txt") or readfile(FOLDER .. "/version.txt") ~= VERSION

		for spritesheet = 1, 2 do
			local Path = `{FOLDER}/{spritesheet}.png`

			if ShouldUpdate or not isfile(Path) then
				local Data = game:HttpGet(`{SHEETS}{spritesheet}.png`)

				-- only a real picture is kept (a failed download would show no icons at all)
				assert(type(Data) == "string" and Data:sub(1, 4) == "\137PNG", "sprite sheet download failed")
				writefile(Path, Data)
			end
		end

		writefile(FOLDER .. "/version.txt", VERSION)

		return getcustomasset(FOLDER .. "/1.png")
	end)

	-- no sheets on disk: the same pictures uploaded to Roblox are used instead
	IS_GETCUSTOMASSET_BROKEN = not Ok
end

